<?php use yii\helpers\Html;$this->title='Dosen Pengajar';?>
<div class="d-flex justify-content-between mb-3"><div><h1 class="mb-0">Dosen Pengajar</h1><span class="text-muted">Dosen Pengajar Kelas</span></div><div><?=Html::a('Kembali ke Daftar',['index'],['class'=>'btn btn-primary'])?> <?=Html::a('<i class="fas fa-edit"></i> Edit',['lecturer-update','id'=>$model->id],['class'=>'btn btn-warning'])?></div></div><div class="card card-success card-outline"><div class="card-body"><div class="row"><div class="col-md-2"><?=$this->render('_detail_nav',['model'=>$model,'active'=>'lecturers'])?></div><div class="col-md-10"><?=$this->render('_class_summary',['model'=>$model])?><h5 class="text-primary">Dosen Pengajar</h5><table class="table table-striped"><tbody><?php foreach($model->lecturers as $lecturer):?><tr><td><?=Html::encode($lecturer->employee->user->name??'-')?></td><td class="text-right"><?=$lecturer->id==$model->coordinator_lecturer_id?'<span class="badge badge-success">Penanggung Jawab Mata Kuliah</span>':''?></td></tr><?php endforeach?><?php if(!$model->lecturers):?><tr><td class="text-muted">Belum ada dosen pengajar.</td></tr><?php endif?></tbody></table></div></div></div></div>
